import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, arrival)
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    counter = 0

    def clean_buy():
        while buy_heap:
            negprice, arrival, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, arrival, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['qty'] > 0:
                info['qty'] = 0
                del book[oid]
            continue

        counter += 1
        arrival = counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sprice, sarrival, sid = sell_heap[0]
                if typ != 'market' and price < sprice:
                    break
                heapq.heappop(sell_heap)
                sinfo = book[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] > 0:
                    heapq.heappush(sell_heap, (sprice, sarrival, sid))
                else:
                    del book[sid]
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, barrival, bid = buy_heap[0]
                bprice = -negprice
                if typ != 'market' and price > bprice:
                    break
                heapq.heappop(buy_heap)
                binfo = book[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] > 0:
                    heapq.heappush(buy_heap, (negprice, barrival, bid))
                else:
                    del book[bid]

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        # for ioc/market, remainder discarded (do nothing)

    return trades

